    cb=[]; prev=0
    for c in clines+[W]: cb.append((prev,c)); prev=c+1
    vals=sorted({x for row in g for x in row if x not in (0,8)})
    for v in vals:
        occ={}
        for i,(r0,r1) in enumerate(rb):
            for j,(c0,c1) in enumerate(cb):
                s={(r-r0,c-c0) for r in range(r0,r1) for c in range(c0,c1) if g[r][c]==v}
                if s: occ[(i,j)]=s
        ks=sorted(occ)
        iset={(i,j) for i,j in ks}
        # find missing cell(s): 2x2 blocks with 3 occupied
        for i,j in list(ks):
            for di,dj in [(1,1),(1,-1),(-1,1),(-1,-1)]:
                corner=(i,j); miss=(i+di,j+dj); side1=(i,j+dj); side2=(i+di,j)
                if miss in occ or miss not in occ: 
                    if miss in occ: continue
                if side1 in occ and side2 in occ and 0<=miss[0]<len(rb) and 0<=miss[1]<len(cb):
                    s=occ[corner]; h=r1-r0 if False else rb[corner[0]][1]-rb[corner[0]][0]
